"""Tests of ``picasso.legacy``: files written before Picasso 1.0 (lengths
in camera pixels) are converted to the current format (nm).

:author: Picasso Developers, 2026
:copyright: Copyright (c) 2026 Jungmann Lab, MPI of Biochemistry
"""

import json
import os

import h5py
import numpy as np
import pandas as pd
import pytest
import yaml

from picasso import io, legacy, lib, transforms

PS = 130.0
INFO = [
    {"Width": 64, "Height": 64, "Frames": 100, "Pixelsize": PS},
    {
        "Generated by": "Picasso Filter",
        "sx": [0.8, 1.2],
        "lpx": [0.0, 0.1],
        "photons": [100, None],
    },
    {"Generated by": "Picasso Render"},
]


@pytest.fixture(autouse=True)
def _yaml_sidecar_off(monkeypatch):
    monkeypatch.setattr(io, "_save_metadata_in_yaml", lambda: False)


def _legacy_locs(n: int = 50, seed: int = 0) -> pd.DataFrame:
    """Localizations in camera pixels, as Picasso wrote them before 1.0."""
    rng = np.random.default_rng(seed)
    return pd.DataFrame(
        {
            "frame": rng.integers(0, 100, n).astype(np.uint32),
            "x": rng.uniform(0, 64, n).astype(np.float32),
            "y": rng.uniform(0, 64, n).astype(np.float32),
            "lpx": np.full(n, 0.1, np.float32),
            "lpy": np.full(n, 0.1, np.float32),
            "sx": np.full(n, 0.9, np.float32),
            "photons": np.full(n, 1000.0, np.float32),
            "likelihood": np.full(n, -3.0, np.float32),
        }
    )


def _write_legacy(path, locs, info=INFO) -> str:
    """A file without the format marker, i.e., in camera pixels."""
    with h5py.File(path, "w") as f:
        f.create_dataset("locs", data=locs.to_records(index=False))
        f.create_dataset("metadata", data=json.dumps(info))
    return str(path)


class TestColumns:
    def test_column_power(self):
        columns = ["x", "y", "lpx", "area", "convexhull", "z", "frame"]
        assert legacy.column_power("x", columns) == 1
        assert legacy.column_power("area", columns) == 2
        assert legacy.column_power("volume", columns) == 3
        assert legacy.column_power("d_zcalib", columns) == 0.5
        assert legacy.column_power("x_mean", columns) == 1
        assert legacy.column_power("lpx_std", columns) == 1
        assert legacy.column_power("frame", columns) is None
        assert legacy.column_power("z", columns) is None
        assert legacy.column_power("photons_mean", columns) is None
        # a convex hull is an area for 2D clusters, a volume for 3D ones
        assert legacy.column_power("convexhull", ["x", "convexhull"]) == 2
        assert legacy.column_power("convexhull", columns) == 3

    def test_locs_to_nm(self):
        locs = _legacy_locs()
        locs["area"] = np.float32(2.0)
        converted = legacy.locs_to_nm(locs, PS)
        np.testing.assert_allclose(converted["x"], locs["x"] * PS, rtol=1e-6)
        np.testing.assert_allclose(converted["lpx"], 0.1 * PS, rtol=1e-6)
        np.testing.assert_allclose(converted["area"], 2.0 * PS**2, rtol=1e-6)
        assert converted["x"].dtype == np.float32
        np.testing.assert_array_equal(converted["photons"], locs["photons"])
        np.testing.assert_array_equal(converted["frame"], locs["frame"])
        # the input is untouched
        assert locs["x"].max() < 64

    def test_pixelsize_required(self):
        with pytest.raises(io.MissingPixelsizeError):
            legacy.locs_to_nm(_legacy_locs(), None)
        with pytest.raises(ValueError):
            legacy.locs_to_nm(_legacy_locs(), -1.0)


class TestMetadata:
    def test_info_to_nm(self):
        info = legacy.info_to_nm(INFO, PS, source="old.hdf5")
        # untouched
        assert INFO[1]["sx"] == [0.8, 1.2]
        # Filter ranges of pixel columns are scaled, others kept
        assert info[1]["sx"] == pytest.approx([0.8 * PS, 1.2 * PS])
        assert info[1]["lpx"] == pytest.approx([0.0, 0.1 * PS])
        assert info[1]["photons"] == [100, None]
        # other entries are kept
        assert info[2] == INFO[2]
        # the conversion is recorded and gives the pixel size
        assert info[-1]["Step"] == "Convert units"
        assert info[-1]["Pixelsize"] == PS
        assert info[-1]["Converted from"] == "old.hdf5"
        assert lib.get_from_metadata(info, "Pixelsize") == PS


class TestPicks:
    def test_picks_to_nm(self):
        regions = {
            "Shape": "Brush",
            "Strokes": [{"Width (nm)": 100.0, "Path": [[1.0, 2.0]]}],
        }
        converted = legacy.picks_to_nm(regions, PS)
        assert converted["Strokes"][0]["Path"] == [[1.0 * PS, 2.0 * PS]]
        assert converted["Strokes"][0]["Width (nm)"] == 100.0
        assert converted[io.FORMAT_VERSION_ATTR] == io.FORMAT_VERSION
        # the oldest files: sizes in camera pixels under bare keys
        old = {"Centers": [[1.0, 1.0]], "Diameter": 2.0}
        converted = legacy.picks_to_nm(old, PS)
        assert converted["Diameter (nm)"] == 2.0 * PS
        assert "Diameter" not in converted


class TestDrift:
    def test_drift_file_round_trip(self, tmp_path):
        drift = pd.DataFrame({"x": [0.0, 1.5], "y": [0.0, -2.0]})
        path = str(tmp_path / "legacy_drift.txt")
        np.savetxt(path, drift.to_numpy())  # no header: camera pixels
        assert legacy.file_kind(path) == "drift"
        assert legacy.needs_conversion(path)
        with pytest.raises(io.MissingPixelsizeError):
            io.load_drift(path)
        loaded = io.load_drift(path, pixelsize=PS)
        np.testing.assert_allclose(loaded["x"], drift["x"] * PS)
        out = legacy.convert_file(path, pixelsize=PS)
        assert out == str(tmp_path / "legacy_drift_nm.txt")
        assert not legacy.needs_conversion(out)
        again = io.load_drift(out)  # no pixel size needed any more
        np.testing.assert_allclose(again["y"], drift["y"] * PS)
        with open(out) as f:
            assert f.readline().startswith("# picasso_format 1.0")


class TestCalibrations:
    def test_calibration_to_nm(self):
        transform = transforms.TranslationTransform.from_shift((1.0, -0.5))
        calibration = {
            "X Coefficients": [0.0, 1.0],
            "Y Coefficients": [0.0, 1.2],
            "Magnification factor": 0.79,
            lib.LATERAL_TRANSFORMS_KEY: [
                {"Type": "chromatic", "Transform": transform.to_dict()}
            ],
        }
        converted = legacy.calibration_to_nm(calibration, PS)
        assert converted["X Coefficients"] == [0.0, PS]
        assert converted["Magnification factor"] == 0.79
        moved = lib.lateral_transform_models(converted)[0]
        np.testing.assert_allclose(
            moved.apply([[0.0, 0.0]]), [[PS, -0.5 * PS]]
        )
        assert converted[io.FORMAT_VERSION_ATTR] == io.FORMAT_VERSION
        assert calibration["X Coefficients"] == [0.0, 1.0]  # untouched

    def test_load_calibration_converts_legacy_files(self, tmp_path):
        path = str(tmp_path / "calib.yaml")
        with open(path, "w") as f:
            yaml.safe_dump(
                {"X Coefficients": [0.0, 1.0], "Y Coefficients": [0.0, 1.0]}, f
            )
        with pytest.raises(io.MissingPixelsizeError):
            io.load_calibration(path)
        calibration = io.load_calibration(path, pixelsize=PS)
        assert calibration["X Coefficients"] == [0.0, PS]
        # saved files carry the marker and load without a pixel size
        out = str(tmp_path / "calib_nm.yaml")
        io.save_calibration(out, calibration)
        assert io.load_calibration(out)["X Coefficients"] == [0.0, PS]
        assert legacy.file_kind(path) == "calibration"
        assert legacy.convert_file(path, pixelsize=PS) == out

    def test_mask_and_nanotron(self):
        mask = legacy.mask_info_to_nm(
            {"x_min": 0, "x_max": 512.0, "Camera pixelsize (nm)": PS}
        )
        assert mask["x_max"] == 512.0 * PS
        model = legacy.nanotron_model_to_nm(
            {"Pick Diameter": 1.0, "Oversampling": 50}, PS
        )
        assert model["Pick Diameter (nm)"] == PS
        assert model["Display pixel size (nm)"] == pytest.approx(PS / 50)
        assert "Oversampling" not in model


class TestFiles:
    def test_file_kinds(self, tmp_path):
        path = _write_legacy(tmp_path / "old_locs.hdf5", _legacy_locs())
        assert legacy.file_kind(path) == "locs"
        assert legacy.needs_conversion(path)
        picks = tmp_path / "old_locs_picks.yaml"
        picks.write_text(
            "Shape: Circle\nCenters: [[1.0, 2.0]]\nDiameter (nm): 100\n"
        )
        assert legacy.file_kind(str(picks)) == "picks"
        other = tmp_path / "notes.txt"
        other.write_text("hello\n")
        assert legacy.file_kind(str(other)) is None
        assert not legacy.needs_conversion(str(other))
        with pytest.raises(ValueError, match="not a file Picasso converts"):
            legacy.convert_file(str(other))

    def test_convert_locs_file(self, tmp_path):
        locs = _legacy_locs()
        path = _write_legacy(tmp_path / "old_locs.hdf5", locs)
        out = legacy.convert_file(path)  # Pixelsize from the metadata
        assert out == str(tmp_path / "old_locs_nm.hdf5")
        assert io.get_format_version(out) == (1, 0)
        assert not legacy.needs_conversion(out)
        loaded, info = io.load_locs(out)
        np.testing.assert_allclose(loaded["x"], locs["x"] * PS, rtol=1e-6)
        assert "log_likelihood" in loaded.columns
        assert info[-1]["Step"] == "Convert units"
        assert info[1]["sx"] == pytest.approx([0.8 * PS, 1.2 * PS])
        # the original is untouched and still legacy
        assert legacy.needs_conversion(path)
        with pytest.raises(ValueError, match="current format already"):
            legacy.convert_file(out)

    def test_convert_in_place_with_sidecar(self, tmp_path):
        locs = _legacy_locs()
        path = _write_legacy(tmp_path / "old_locs.hdf5", locs)
        with open(tmp_path / "old_locs.yaml", "w") as f:
            yaml.safe_dump_all(INFO, f)
        out = legacy.convert_file(
            str(tmp_path / "old_locs.yaml"), in_place=True
        )
        assert out == path
        assert not legacy.needs_conversion(path)
        # the sidecar (which takes precedence) was converted as well
        info = io.load_info(path)
        assert info[-1]["Step"] == "Convert units"
        loaded, _ = io.load_locs(path)
        np.testing.assert_allclose(loaded["x"], locs["x"] * PS, rtol=1e-6)
        assert not any(
            name.endswith(".yaml") and "old_locs_" in name
            for name in os.listdir(tmp_path)
        )

    def test_convert_spline_file(self, tmp_path):
        # a spline calibration written before Picasso 1.0 records the
        # pixel size; its lateral correction is in camera pixels
        path = str(tmp_path / "spline.hdf5")
        transform = transforms.TranslationTransform.from_shift((1.0, -0.5))
        metadata = {
            "model": "spline-3d",
            "pixelsize": PS,
            lib.LATERAL_TRANSFORMS_KEY: [
                {"Type": "chromatic", "Transform": transform.to_dict()}
            ],
        }
        with h5py.File(path, "w") as f:
            f.create_dataset("coefficients", data=np.zeros((2, 64), "f4"))
            f.attrs["metadata"] = json.dumps(metadata)
        assert legacy.file_kind(path) == "spline"
        assert legacy.needs_conversion(path)
        output = legacy.convert_file(path)
        assert not legacy.needs_conversion(output)
        written = io._read_spline_calibration(output)
        assert written[io.FORMAT_VERSION_ATTR] == io.FORMAT_VERSION
        # converted once: the shift is scaled by the pixel size, not its
        # square
        moved = lib.lateral_transform_models(written)[0]
        np.testing.assert_allclose(
            moved.apply([[0.0, 0.0]]), [[PS, -0.5 * PS]]
        )
        with pytest.raises(ValueError, match="already"):
            legacy.convert_file(output)

    def test_missing_pixelsize(self, tmp_path):
        info = [{k: v for k, v in INFO[0].items() if k != "Pixelsize"}]
        path = _write_legacy(tmp_path / "old_locs.hdf5", _legacy_locs(), info)
        with pytest.raises(io.MissingPixelsizeError):
            legacy.convert_file(path)
        out = legacy.convert_file(path, pixelsize=PS)
        loaded, info = io.load_locs(out)
        assert lib.get_from_metadata(info, "Pixelsize") == PS

    def test_convert_files_reports_each_file(self, tmp_path):
        path = _write_legacy(tmp_path / "a_locs.hdf5", _legacy_locs())
        picks = tmp_path / "a_locs_picks.yaml"
        picks.write_text(
            "Shape: Circle\nCenters: [[1.0, 2.0]]\nDiameter (nm): 100\n"
        )
        other = tmp_path / "notes.txt"
        other.write_text("hello\n")
        recorder = _PhaseRecorder()
        results = legacy.convert_files(
            [path, str(picks), str(other), path],
            pixelsize=PS,
            progress=recorder,
        )
        assert [r[0] for r in results] == [path, str(picks), str(other), path]
        assert results[0][1] == str(tmp_path / "a_locs_nm.hdf5")
        assert results[1][1] == str(tmp_path / "a_locs_picks_nm.yaml")
        assert results[2][1] is None and "not a file" in results[2][2]
        assert results[3][1] is None and "twice" in results[3][2]
        # one phase over the files, skipped ones included
        assert recorder.phases == [
            {
                "label": "Converting files",
                "maximum": 4,
                "values": [1, 2, 3, 4, 4],
            }
        ]
        converted, shape, size = io.load_picks(results[1][1])
        assert converted == [[1.0 * PS, 2.0 * PS]] and size == 100

    def test_groups_file(self, tmp_path):
        groups = pd.DataFrame(
            {
                "group": [0, 1],
                "x_mean": [1.0, 2.0],
                "x_std": [0.1, 0.2],
                "n_events": [3, 4],
            }
        )
        path = str(tmp_path / "old_groupprops.hdf5")
        with h5py.File(path, "w") as f:
            f.create_dataset("groups", data=groups.to_records(index=False))
            f.create_dataset("metadata", data=json.dumps(INFO))
        out = legacy.convert_file(path)
        loaded, _ = io.load_filter(out)
        np.testing.assert_allclose(loaded["x_mean"], [PS, 2 * PS])
        np.testing.assert_allclose(loaded["x_std"], [0.1 * PS, 0.2 * PS])
        np.testing.assert_array_equal(loaded["n_events"], [3, 4])


class _PhaseRecorder(lib.MockProgress):
    """Progress tracker recording the phases it is driven through."""

    def __init__(self):
        super().__init__()
        self.phases = []  # dicts with "label", "maximum" and "values"

    def zero_progress(self, description=None, *args, **kwargs):
        super().zero_progress(description)
        self.phases.append({"label": description, "maximum": 0, "values": []})

    def setMaximum(self, maximum, *args, **kwargs):
        super().setMaximum(maximum)
        self.phases[-1]["maximum"] = maximum

    def set_value(self, value, *args, **kwargs):
        self.phases[-1]["values"].append(value)


class TestProgress:
    def _picks(self, tmp_path):
        picks = tmp_path / "old_picks.yaml"
        picks.write_text(
            "Shape: Circle\nCenters: [[1.0, 2.0]]\nDiameter (nm): 100\n"
        )
        return str(picks)

    def test_convert_file_locs_reports_the_read(self, tmp_path):
        path = _write_legacy(tmp_path / "old_locs.hdf5", _legacy_locs(20))
        recorder = _PhaseRecorder()
        legacy.convert_file(path, pixelsize=PS, progress=recorder)
        assert recorder.phases == [
            {"label": "Loading localizations", "maximum": 20, "values": [20]}
        ]

    @pytest.mark.parametrize("in_place", [False, True])
    def test_convert_file_other_kinds_one_step(self, tmp_path, in_place):
        recorder = _PhaseRecorder()
        legacy.convert_file(
            self._picks(tmp_path),
            pixelsize=PS,
            in_place=in_place,
            progress=recorder,
        )
        assert recorder.phases == [
            {"label": "Converting old_picks.yaml", "maximum": 1, "values": [1]}
        ]

    def test_none_is_silent_and_console_works(self, tmp_path, capsys):
        path = _write_legacy(tmp_path / "a_locs.hdf5", _legacy_locs(20))
        picks = self._picks(tmp_path)
        legacy.convert_file(path, pixelsize=PS, in_place=True)
        legacy.convert_files([picks], pixelsize=PS, progress=None)
        captured = capsys.readouterr()
        assert captured.out == "" and captured.err == ""
        path = _write_legacy(tmp_path / "b_locs.hdf5", _legacy_locs(20))
        legacy.convert_file(path, pixelsize=PS, progress="console")
        assert "Loading localizations" in capsys.readouterr().err
        legacy.convert_files([picks], pixelsize=PS, progress="console")
        assert "Converting files" in capsys.readouterr().err

    def test_cancel_stops_the_batch(self, tmp_path):
        # a canceled tracker is not reported as an error of one file
        picks = self._picks(tmp_path)

        class Cancel(_PhaseRecorder):
            def set_value(self, value, *args, **kwargs):
                raise lib.OperationCanceled

        with pytest.raises(lib.OperationCanceled):
            legacy.convert_files([picks, picks], progress=Cancel())
